plural <- function(n) {
  if (n == 1) return("one")
  if (n == 2) return("two")
  mod100 <- n %% 100
  if (n == 0 || (mod100 >= 3 && mod100 <= 10)) return("few")
  if (mod100 >= 11 && mod100 <= 19) return("many")
  "other"
}

